<?php
require_once __DIR__.'/functions.php';$u=require_login();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';if($action==='folder'){$name=trim($_POST['folder_name']??'');if($name==='')flash('Nama folder wajib diisi.','error');else{try{$s=$pdo->prepare('INSERT INTO folders(user_id,name) VALUES(?,?)');$s->execute([$u['id'],$name]);flash('Folder berhasil dibuat.');}catch(PDOException $e){flash('Folder sudah ada atau nama tidak valid.','error');}}redirect('dashboard.php');}
if($action==='upload'){if(!isset($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK) {flash('Upload gagal. Periksa ukuran file.','error');redirect('dashboard.php');}$f=$_FILES['file'];if($f['size']>MAX_UPLOAD_BYTES){flash('Ukuran maksimum file adalah 20 MB.','error');redirect('dashboard.php');}$used=used_bytes((int)$u['id']);$s=$pdo->prepare('SELECT quota_bytes FROM users WHERE id=?');$s->execute([$u['id']]);$quota=(int)$s->fetchColumn();if($used+$f['size']>$quota){flash('Kuota penyimpanan tidak mencukupi.','error');redirect('dashboard.php');}$folderId=($_POST['folder_id']??'')!==''?(int)$_POST['folder_id']:null;if($folderId){$s=$pdo->prepare('SELECT id FROM folders WHERE id=? AND user_id=?');$s->execute([$folderId,$u['id']]);if(!$s->fetch())$folderId=null;}$stored=bin2hex(random_bytes(32));$original=safe_filename($f['name']);$mime='application/octet-stream';if(function_exists('finfo_open')){$fi=finfo_open(FILEINFO_MIME_TYPE);if($fi){$mime=finfo_file($fi,$f['tmp_name'])?:$mime;finfo_close($fi);}}try{$plain=file_get_contents($f['tmp_name']);$encrypted=encrypt_file($plain);if(!is_dir(STORAGE_DIR))mkdir(STORAGE_DIR,0700,true);if(file_put_contents(STORAGE_DIR.'/'.$stored.'.enc',$encrypted,LOCK_EX)===false)throw new RuntimeException('Tidak dapat menyimpan file.');$s=$pdo->prepare('INSERT INTO files(user_id,folder_id,original_name,stored_name,mime_type,size_bytes) VALUES(?,?,?,?,?,?)');$s->execute([$u['id'],$folderId,$original,$stored,$mime,$f['size']]);flash('File berhasil diupload dan dienkripsi.');}catch(Throwable $e){if(isset($stored)&&is_file(STORAGE_DIR.'/'.$stored.'.enc'))unlink(STORAGE_DIR.'/'.$stored.'.enc');flash('Upload gagal: '.$e->getMessage(),'error');}redirect('dashboard.php');}}
$used=used_bytes((int)$u['id']);$s=$pdo->prepare('SELECT quota_bytes FROM users WHERE id=?');$s->execute([$u['id']]);$quota=(int)$s->fetchColumn();$s=$pdo->prepare('SELECT * FROM folders WHERE user_id=? ORDER BY name');$s->execute([$u['id']]);$folders=$s->fetchAll();$s=$pdo->prepare('SELECT f.*,fo.name folder_name FROM files f LEFT JOIN folders fo ON fo.id=f.folder_id WHERE f.user_id=? ORDER BY f.created_at DESC');$s->execute([$u['id']]);$files=$s->fetchAll();
page_header('Dashboard'); ?><div class="page-heading"><div><div class="eyebrow">RUANG PENYIMPANAN</div><h1>Halo, <?=e($u['name'])?> 👋</h1><p class="muted">Kelola dokumen kuliahmu di satu tempat.</p></div><span class="role-pill">MAHASISWA</span></div><section class="panel quota"><div class="quota-top"><div><span class="muted">Penyimpanan digunakan</span><h2><?=e(format_bytes($used))?> <small>/ <?=e(format_bytes($quota))?></small></h2></div><strong><?= $quota>0?round(min(100,$used/$quota*100)):0 ?>%</strong></div><div class="progress"><span style="width:<?= $quota>0?min(100,$used/$quota*100):0 ?>%"></span></div></section><div class="two-col"><section class="panel"><h2>Upload file</h2><p class="muted">Maksimum 20 MB per file. File dienkripsi sebelum disimpan.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="upload"><label>Pilih file</label><input type="file" name="file" required><label>Simpan ke folder</label><select name="folder_id"><option value="">Folder utama</option><?php foreach($folders as $fo): ?><option value="<?=$fo['id']?>"><?=e($fo['name'])?></option><?php endforeach; ?></select><button class="primary">Upload file</button></form></section><section class="panel"><h2>Buat folder</h2><p class="muted">Kelompokkan file berdasarkan mata kuliah atau kebutuhan.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="folder"><label>Nama folder</label><input name="folder_name" maxlength="120" placeholder="Contoh: Pemrograman Web" required><button class="secondary">+ Buat folder</button></form><div class="folder-list"><?php foreach($folders as $fo): ?><span>📁 <?=e($fo['name'])?></span><?php endforeach; ?><?php if(!$folders): ?><span class="muted">Belum ada folder.</span><?php endif; ?></div></section></div><section class="panel"><div class="section-title"><h2>File saya</h2><span class="muted"><?=count($files)?> file</span></div><?php if(!$files): ?><div class="empty">Belum ada file. Upload file pertamamu di atas.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Nama file</th><th>Folder</th><th>Ukuran</th><th>Tanggal</th><th>Aksi</th></tr></thead><tbody><?php foreach($files as $f): ?><tr><td>📄 <?=e($f['original_name'])?></td><td><?=e($f['folder_name']??'Utama')?></td><td><?=e(format_bytes((int)$f['size_bytes']))?></td><td><?=e($f['created_at'])?></td><td class="actions"><a href="download.php?id=<?=$f['id']?>">Download</a><form method="post" action="share.php" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="file_id" value="<?=$f['id']?>"><button class="link-button">Buat link</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php page_footer(); ?>
